<?php require_once 'includes/bootstrap.php'; $pdo=db(); $q=trim($_GET['q']??''); if($q){$stmt=$pdo->prepare("SELECT * FROM courses WHERE is_active=1 AND (title LIKE ? OR short_description LIKE ? OR topics LIKE ?) ORDER BY title"); $like='%'.$q.'%'; $stmt->execute([$like,$like,$like]); $courses=$stmt->fetchAll();}else{$courses=$pdo->query("SELECT * FROM courses WHERE is_active=1 ORDER BY title")->fetchAll();} page_head('Courses','Explore online courses in web development, data analytics, artificial intelligence, cyber security and digital skills.'); site_header('courses.php'); render_flash(); ?>
<main><section class="page-hero"><div class="page-hero-content"><p class="section-label">LEARNING OPPORTUNITIES</p><h1>Explore Our Courses</h1><p>Search the catalogue and choose a learning area that matches your goals.</p></div></section><section><form class="search-form" method="get" action="courses.php" role="search"><label for="q">Search courses</label><div><input id="q" name="q" value="<?= e($q) ?>" placeholder="e.g. cyber security" maxlength="80"><button class="button primary-button" type="submit">Search</button></div></form><div class="section-heading left"><p class="section-label">COURSE CATALOGUE</p><h2>Choose Your Learning Area</h2><p><?= count($courses) ?> course(s) available.</p></div><div class="course-grid"><?php foreach($courses as $c): ?><article class="course-card"><img src="<?= e(url('images/'.$c['image'])) ?>" alt="Course image for <?= e($c['title']) ?>"><div class="course-card-body"><span class="badge"><?= e($c['level']) ?></span><h3><?= e($c['title']) ?></h3><p><?= e($c['short_description']) ?></p><ul class="compact-list"><li><strong>Topics:</strong> <?= e($c['topics']) ?></li><li><strong>Format:</strong> Online learning</li></ul><a class="button secondary-button small" href="<?= e(url('course.php?id='.$c['id'])) ?>">View details →</a></div></article><?php endforeach; ?></div><?php if(!$courses): ?><div class="card center"><h2>No courses found</h2><p>Try another keyword.</p></div><?php endif; ?></section></main><?php site_footer(); ?>